import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
/**
 * Server-side flag context construction and the org-level override toggle.
 *
 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
 */
import { emit } from "@/lib/event-bus";
import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { getFlagDefinition } from "@/config/feature-flags";
import * as orgRepo from "@/server/repositories/organization-repository";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/**
 * Builds the evaluation context every `isEnabled()` call needs. Both halves
 * are nullable so marketing pages — no session, no org — can still ask about
 * a flag and get the free-plan answer.
 */
export function buildFlagContext(
  actor: Actor | null,
  org: Organization | null,
): FlagContext {
  return {
    orgId: org?.id ?? actor?.orgId ?? null,
    userId: actor?.userId ?? null,
    plan: org?.plan ?? "free",
    role: actor?.role ?? null,
    overrides: org?.settings.enabledFlagOverrides,
  };
}

/**
 * The serialisable snapshot the dashboard layout hands to the client provider,
 * so `useFeatureFlag()` answers without a round trip and cannot disagree with
 * the server.
 */
export function getSnapshot(
  actor: Actor,
  org: Organization,
): FeatureFlagSnapshot {
  return snapshotFlags(buildFlagContext(actor, org));
}

/**
 * Adds or removes an org-level override. Only flags declared `overridable`
 * accept one — a flag gated purely on plan cannot be switched on by an admin,
 * which is what keeps the plan boundary meaningful.
 */
export async function toggleFlag(
  actor: Actor,
  input: ToggleFeatureFlagInput,
): Promise<Organization> {
  assertCan(actor, "org:manage_flags", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const definition = getFlagDefinition(input.flag);
  if (!definition.overridable && definition.strategy.kind !== "plan") {
    throw new Error(`Feature "${input.flag}" cannot be overridden per org`);
  }

  const current = new Set(org.settings.enabledFlagOverrides);
  if (input.enabled) {
    current.add(input.flag);
  } else {
    current.delete(input.flag);
  }

  const updated = await orgRepo.updateOrg(input.orgId, {
    orgId: input.orgId,
    settings: { enabledFlagOverrides: [...current] },
  });

  await emit("flag.toggled", {
    ...actorEnvelope(actor),
    flag: input.flag,
    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),
  });

  return updated;
}
"use server";

/**
 * Toggles an org-level feature flag override.
 *
 * Owner D. An override can only *turn on* a flag whose definition is
 * `overridable`; `isEnabled()` is consulted first so that toggling a flag which
 * is already on for structural reasons (plan or rollout percentage) is a no-op
 * rather than a confusing write.
 *
 * Must call (do not reimplement): toggleFeatureFlagSchema, can, isEnabled,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import {
  toggleFeatureFlagSchema,
  type ToggleFeatureFlagInput,
} from "@/schemas/feature-flag";
import {
  buildFlagContext,
  toggleFlag,
} from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";

const run = withAction<typeof toggleFeatureFlagSchema, Organization>(
  toggleFeatureFlagSchema,
  async (raw, actor) => {
    const input = raw as ToggleFeatureFlagInput;

    if (!can(actor, "org:manage_flags", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:manage_flags");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    const context = buildFlagContext(actor, organization);
    if (isEnabled(input.flag, context) === input.enabled) {
      return organization;
    }

    const updated = await toggleFlag(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return updated;
  },
  { revalidate: ["flags"], cacheProfile: "minutes" },
);

export async function toggleFeatureFlagAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}
import type { OrgId, UserId } from "./common";
import type { PlanId } from "./billing";
import type { Role } from "./member";

/**
 * Every feature flag known to Taskflow. Adding a key here obliges you to add a
 * matching entry to `FEATURE_FLAG_DEFINITIONS` in `src/config/feature-flags.ts`
 * — the type is what keeps the two in sync.
 */
export type FeatureFlagKey =
  | "kanban_board"
  | "ai_issue_summary"
  | "command_palette"
  | "activity_feed"
  | "public_projects"
  | "webhooks"
  | "csv_export"
  | "digest_email"
  | "issue_templates"
  | "advanced_search";

export type FlagRolloutStrategy =
  | { readonly kind: "off" }
  | { readonly kind: "on" }
  | { readonly kind: "plan"; readonly minPlan: PlanId }
  | { readonly kind: "role"; readonly minRole: Role }
  | { readonly kind: "percentage"; readonly percent: number };

export interface FeatureFlagDefinition {
  readonly key: FeatureFlagKey;
  readonly label: string;
  readonly description: string;
  readonly strategy: FlagRolloutStrategy;
  /** When true the org-level override in `OrganizationSettings` can turn it on. */
  readonly overridable: boolean;
}

/**
 * Evaluation context passed to `isEnabled()`. The same shape is used on the
 * server (built from the session) and in the client via `useFeatureFlag`.
 */
export interface FlagContext {
  readonly orgId: OrgId | null;
  readonly userId: UserId | null;
  readonly plan: PlanId;
  readonly role: Role | null;
  readonly overrides?: readonly string[];
}

/** Serialisable snapshot handed from a server layout to the client provider. */
export type FeatureFlagSnapshot = Readonly<Record<FeatureFlagKey, boolean>>;
import { z } from "zod";
import type { FeatureFlagKey } from "@/types/feature-flag";
import { orgIdSchema, userIdSchema } from "./common";
import { planIdSchema } from "./billing";
import { roleSchema } from "./role";

export const featureFlagKeySchema = z.enum([
  "kanban_board",
  "ai_issue_summary",
  "command_palette",
  "activity_feed",
  "public_projects",
  "webhooks",
  "csv_export",
  "digest_email",
  "issue_templates",
  "advanced_search",
]);

export const toggleFeatureFlagSchema = z.object({
  orgId: orgIdSchema,
  flag: featureFlagKeySchema,
  enabled: z.boolean(),
});

export const flagContextSchema = z.object({
  orgId: orgIdSchema.nullable(),
  userId: userIdSchema.nullable(),
  plan: planIdSchema,
  role: roleSchema.nullable(),
  overrides: z.array(z.string()).optional(),
});

const _flagParity: FeatureFlagKey = "kanban_board" satisfies z.infer<
  typeof featureFlagKeySchema
>;
void _flagParity;

export type ToggleFeatureFlagInput = z.infer<typeof toggleFeatureFlagSchema>;
export type FlagContextInput = z.infer<typeof flagContextSchema>;
/**
 * Cross-cutting constants that are neither plan limits nor flags (page sizes,
 * edit windows, retry counts).
 *
 * Quotas live in `@/config/plan-limits` and rollout gates in
 * `@/config/feature-flags`; anything that is neither — a default page size, a
 * grace window, a retry budget — belongs here so the number exists once.
 */

/** Rows per page for every cursor-paginated list unless the caller overrides. */
export const DEFAULT_PAGE_SIZE: number = 25;

/** Upper bound the pagination schemas clamp `limit` to. */
export const MAX_PAGE_SIZE: number = 100;

/** How long after posting a comment its author may still edit it. */
export const COMMENT_EDIT_WINDOW_MINUTES: number = 15;

/** Delivery attempts before the webhook dispatcher parks a delivery. */
export const WEBHOOK_MAX_ATTEMPTS: number = 5;

/** Hard cap on entries rendered in one digest email. */
export const DIGEST_MAX_ENTRIES: number = 50;

/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

